import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

# Check various matches
matches_by_displayname = []
matches_with_userid = []
for p in data['records']:
    o = p.get('OwnerUserId')
    dn = p.get('OwnerDisplayName')
    if dn and 'slashnick' in str(dn).lower():
        matches_by_displayname.append(p)
    if o == 16 or (isinstance(o, str) and '16' in o):
        if p not in matches_with_userid:
            matches_with_userid.append(p)

print(f"Matches by display name (case-insensitive): {len(matches_by_displayname)}")
for p in matches_by_displayname:
    print(f"Post ID: {p['Id']}, Type: {p.get('PostTypeId')}, AnswerCount: {p.get('AnswerCount')}, OwnerUserId: {p.get('OwnerUserId')}, OwnerDisplayName: {p.get('OwnerDisplayName')}")

print(f"\nMatches by user ID 16: {len(matches_with_userid)}")
for p in matches_with_userid:
    print(f"Post ID: {p['Id']}, Type: {p.get('PostTypeId')}, AnswerCount: {p.get('AnswerCount')}, OwnerUserId: {p.get('OwnerUserId')}, OwnerDisplayName: {p.get('OwnerDisplayName')}")
